def compute(vars):
    not_leased = vars["v1"]
    total = vars["v2"]

    if total == 0:
        return {"value": None, "trace": {"output_meta": {"currency": None, "scale": "percent", "unit": "percentage"}}}

    ratio = not_leased / total
    percentage = ratio * 100

    return {
        "value": percentage,
        "trace": {
            "not_leased_square_feet": not_leased,
            "total_square_feet": total,
            "ratio": ratio,
            "output_meta": {"currency": None, "scale": "percent", "unit": "percentage"}
        }
    }
